    {
      "id": "p1",
      "utteranceIds": ["a303746a-1dd2-4f46-8e6e-cfe90d6b2ff8"],
      "category": "grammar",
      "presentation": "core",
      "title": "「有……嗎？」詢問動作是否完成",
      "sourceCueIds": ["c1"],
      "contextCueIds": [],
      "explanation": "在台灣華語中，常在動詞前加上「有」，構成「你有……嗎？」句型，用來確認某件事情或動作是否已經發生或完成。相當於標準語法中的「你……了嗎？」。",
      "sourceSpans": [
        {"cueId": "c1", "start": 1, "end": 2},
        {"cueId": "c1", "start": 12, "end": 13}
      ]
    },
    {
      "id": "p2",
      "utteranceIds": ["edc7175e-ddaf-4c1c-9e5f-346fca7fa460"],
      "category": "grammar",
      "presentation": "core",
      "title": "「正要……」表示即將進行某動作",
      "sourceCueIds": ["c2"],
      "contextCueIds": [],
      "explanation": "「正要」後面接動詞，表示說話者在此刻剛好打算、正準備採取某個行動，強調時機的緊接性。",
      "sourceSpans": [{"cueId": "c2", "start": 4, "end": 6}]
    },
    {
      "id": "p3",
      "utteranceIds": ["089d1612-a873-4dee-9e86-c3770110de43"],
      "category": "usage",
      "presentation": "core",
      "title": "「那請先……」順應當前情況提出優先請求",
      "sourceCueIds": ["c3"],
      "contextCueIds": ["c2"],
      "explanation": "「那」在此作為承接連詞，表示「既然如此」；結合「請先……」，用在得知對方尚未行動時，及時指引對方在執行時優先加入某項新的處理內容。",
      "sourceSpans": [{"cueId": "c3", "start": 0, "end": 4}]
    }
  ],
